        </div>

        {/* Content */}
        <div style={{flex:1,overflow:"auto",padding:"28px",background:C.bg}}>
          {activeNav==="dashboard"
            ?<Dashboard onNav={setActiveNav}/>
            :<ModulePage key={activeNav} moduleKey={activeNav} notify={notify}/>
          }
        </div>
      </div>
    </div>
  </>);
}
